function logout(){
  stopBgMusic();
  localStorage.removeItem(SESSION_KEY);
  const done = () => location.reload();
  try {
    if(typeof firebase !== 'undefined' && firebase.auth && firebase.auth().currentUser) {
      firebase.auth().signOut().then(done, done);
      return;
    }
  } catch(e) { console.warn(e); }
  done();
}

