function openCardColorPicker() {
  var SKINS = CARD_SKINS;
  var CATEGORIES = [
    { name:'Класика', ids:['gold','onyx','platinum','copper','minimal','silver','bronze','obsidian','steel','ivory','charcoal','chrome'] },
    { name:'Самоцвіти', ids:['sapphire','emerald','amethyst','rosegold','coral','ruby','topaz','opal','garnet','turquoise','citrine','peridot'] },
    { name:'Стихії', ids:['fire','ice','mint','storm','sunset','thunder','earth','volcano','blizzard','tsunami','solar','void'] },
    { name:'Космос і футуризм', ids:['cyber','galaxy','holo','nebula','matrix','synthwave','aurora','plasma','quantum'] },
    { name:'Текстури', ids:['carbon','marble','denim','snake','leopard','wood','concrete','velvet','silk','brushedmetal','camo'] },
    { name:'Особливі', ids:['pastel','xmas','ukraine','halloween','valentine','easter','autumn','spring','diamondelite','midnight'] },
    { name:'Меми', ids:['meme-drake','meme-distracted','meme-womancat','meme-twobuttons','meme-changemymind','meme-successkid','meme-doge','meme-thisisfine','meme-stonks','meme-rollsafe','meme-pikachu','meme-disastergirl','meme-grumpycat','meme-expandingbrain','meme-onedoesnotsimply','meme-ancientaliens','meme-dicaprio','meme-pigeon','meme-batman','meme-spongebob','meme-sadpablo','meme-hidethepain'] },
    { name:'Тренди зумерів', ids:['meme-67kid','meme-skibidi','meme-tralalero','meme-bombardiro','meme-tungtung','meme-chimpanzini','meme-gigachad','meme-sigma','meme-chillguy','meme-ohio','meme-npc','meme-rizzler'] },
  ];
  var byId = {};
  SKINS.forEach(function(s) { byId[s.id] = s; });
  var _act = getActiveCardObj();
  var current = (_act && _act.skin) || (!_act && userData.pendingCardSkin) || 'onyx';
  function swatchHtml(s) {
    var active = current === s.id;
    return '<div onclick="applyCardSkin(\'' + s.id + '\')" class="skin-swatch' + (active?' active':'') + '" style="background:' + s.prev + ';border-color:' + (active ? s.accent : 'rgb(var(--tint-rgb) / 0.08)') + ';color:' + s.accent + ';">' +
      (active ? '<div class="skin-swatch-check">✓</div>' : '') +
      '<div style="font-size:10px;font-weight:700;margin-top:26px;color:' + s.accent + ';text-shadow:0 1px 3px rgb(var(--shade-rgb) / 0.8);">' + s.name + '</div>' +
      '</div>';
  }
  var uploadActive = current === 'custom-photo';
  var html = modalCloseBtn('cardskin') +
    '<div style="display:flex;align-items:center;gap:8px;font-size:15px;font-weight:650;color:var(--fg);margin-bottom:4px;padding-right:36px;">' + ksIcon('palette', 17) + 'Скін картки</div>' +
    '<div style="font-size:11px;color:var(--fg-3);margin-bottom:14px;">' + SKINS.length + ' дизайнів у ' + (CATEGORIES.length + 1) + ' категоріях</div>' +
    '<div style="font-size:11px;color:var(--fg-3);font-weight:650;text-transform:uppercase;letter-spacing:1px;margin-bottom:8px;">Персональне</div>' +
    '<div onclick="uploadCustomCardPhoto()" class="skin-swatch' + (uploadActive?' active':'') + '" style="background:var(--surface-2);border:1.5px dashed var(--line-strong);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;height:80px;color:var(--fg-2);margin-bottom:6px;">' +
    (uploadActive ? '<div class="skin-swatch-check">✓</div>' : '') +
    ksIcon('camera', 20) + '<div style="font-size:11px;font-weight:650;">Завантажити своє фото</div>' +
    '</div>' +
    '<div style="max-height:60vh;overflow-y:auto;">' +
    CATEGORIES.map(function(cat) {
      return '<div style="font-size:11px;color:var(--fg-3);font-weight:650;text-transform:uppercase;letter-spacing:1px;margin:14px 0 8px;">' + cat.name + '</div>' +
        '<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;">' +
        cat.ids.filter(function(id){ return byId[id]; }).map(function(id){ return swatchHtml(byId[id]); }).join('') +
        '</div>';
    }).join('') +
    '</div>';
  openModal('cardskin', html);
}

// Показує/прибирає особисте фото поверх скіна — inline style, бо це унікальні
// дані користувача (не спільний CSS-клас, як решта скінів)
function applyCardPhotoBg(el, skin, photoUrl) {
  if(!el) return;
  // #vcardEl — це зовнішня обгортка з .vcard-front І .vcard-back дітьми (для
  // фліпу картки). Раніше фон ставився на неї саму — тому просвічувався лише
  // крізь .vcard-back (у якого немає власного opaque background), а лицьова
  // сторона лишалась поверх зі своїм стандартним фоном. Треба ставити саме
  // на .vcard-front.
  var front = el.classList && el.classList.contains('vcard-front') ? el : el.querySelector('.vcard-front');
  if(!front) return;
  if(skin === 'custom-photo' && photoUrl) {
    front.style.backgroundImage = 'linear-gradient(rgb(var(--recess-rgb) / calc(0.35 * var(--recess-k))),rgb(var(--recess-rgb) / calc(0.55 * var(--recess-k)))), url(' + photoUrl + ')';
    front.style.backgroundSize = 'cover';
    front.style.backgroundPosition = 'center';
  } else {
    front.style.backgroundImage = '';
    front.style.backgroundSize = '';
    front.style.backgroundPosition = '';
  }
}

function uploadCustomCardPhoto() {
  var input = document.createElement('input');
  input.type = 'file';
  input.accept = 'image/*';
  input.onchange = function() {
    var file = input.files && input.files[0];
    if(!file) return;
    if(file.size > 8 * 1024 * 1024) return notify('Фото завелике (макс 8МБ)', 'error');
    var reader = new FileReader();
    reader.onload = function(e) {
      var img = new Image();
      img.onload = function() {
        // Стискаємо до розумного розміру перед збереженням у Firebase
        var maxW = 500;
        var scale = Math.min(1, maxW / img.width);
        var canvas = document.createElement('canvas');
        canvas.width = Math.round(img.width * scale);
        canvas.height = Math.round(img.height * scale);
        var ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        var dataUrl = canvas.toDataURL('image/jpeg', 0.75);

        var cardEl = document.getElementById('vcardEl');
        if(cardEl) { cardEl.className = 'vcard vcard-skin-custom-photo'; applyCardPhotoBg(cardEl, 'custom-photo', dataUrl); }

        var t = _activeSkinTarget();
        if(t.base && t.local) {
          t.local.skin = 'custom-photo'; t.local.customPhotoUrl = dataUrl;
          db.ref('users/' + currentUser + '/' + t.base + '/skin').set('custom-photo');
          db.ref('users/' + currentUser + '/' + t.base + '/customPhotoUrl').set(dataUrl);
        } else {
          userData.pendingCardSkin = 'custom-photo';
          userData.pendingCardPhotoUrl = dataUrl;
          db.ref('users/' + currentUser + '/pendingCardSkin').set('custom-photo');
          db.ref('users/' + currentUser + '/pendingCardPhotoUrl').set(dataUrl);
        }
        notify('Фото застосовано як скін картки', 'success');
        closeModal('cardskin');
        renderCardPanel();
      };
      img.src = e.target.result;
    };
    reader.readAsDataURL(file);
  };
  input.click();
}

// Скін пишеться на АКТИВНУ картку (linkedCards/<id> або virtualCard), а до
// підключення першої картки — у тимчасовий pendingCardSkin.
function _activeSkinTarget() {
  var a = getActiveCardObj();
  if(a && a.kind === 'axiom') return { base: 'virtualCard', local: userData.virtualCard };
  if(a && userData.linkedCards && userData.linkedCards[a.id]) return { base: 'linkedCards/' + a.id, local: userData.linkedCards[a.id] };
  return { base: null, local: null }; // ще немає картки
}

function applyCardSkin(skinId) {
  var cardEl = document.getElementById('vcardEl');
  if(cardEl) { cardEl.className = 'vcard vcard-skin-' + skinId; applyCardPhotoBg(cardEl, skinId, null); }
  var t = _activeSkinTarget();
  if(t.base && t.local) {
    t.local.skin = skinId; t.local.customPhotoUrl = '';
    db.ref('users/' + currentUser + '/' + t.base + '/skin').set(skinId);
    db.ref('users/' + currentUser + '/' + t.base + '/customPhotoUrl').remove();
  } else {
    userData.pendingCardSkin = skinId;
    db.ref('users/' + currentUser + '/pendingCardSkin').set(skinId);
  }
  notify('Скін застосовано', 'success');
  closeModal('cardskin');
  renderCardPanel();
}

// ─── src/app/38-banners-moderation.js ───
// Тимчасових карток SlotOK більше не існує — жодних термінів дії та
// нагадувань про продовження тут немає.

// ╔══════════════════════════════════════════════════════════════╗
// ║  BANNER CAROUSEL — авто-ротація + свайп + крапки            ║
// ╚══════════════════════════════════════════════════════════════╝
var _bannerIndex = 0;
var _bannerCount = 0;   // рахується з розмітки в initBannerCarousel
var _bannerAutoTimer = null;
var _bannerTouchStartX = 0;
var _bannerTouchDeltaX = 0;
var _bannerDragging = false;

function initBannerCarousel() {
  var dotsEl = document.getElementById('bannerDots');
  var trackEl = document.getElementById('bannerTrack');
  if(!dotsEl || !trackEl) return;

  _bannerCount = trackEl.querySelectorAll('.banner-slide').length;
  if(!_bannerCount) return;

  // Побудова крапок (один раз)
  if(!dotsEl.dataset.built) {
    dotsEl.innerHTML = '';
    for(var i = 0; i < _bannerCount; i++) {
      var d = document.createElement('div');
      d.className = 'banner-dot' + (i === 0 ? ' active' : '');
      d.onclick = (function(idx) { return function() { goToBannerSlide(idx); resetBannerAutoRotate(); }; })(i);
      dotsEl.appendChild(d);
    }
    dotsEl.dataset.built = '1';

    // Touch swipe
    trackEl.addEventListener('touchstart', function(e) {
      _bannerTouchStartX = e.touches[0].clientX;
      _bannerDragging = true;
      trackEl.style.transition = 'none';
    }, { passive: true });

    trackEl.addEventListener('touchmove', function(e) {
      if(!_bannerDragging) return;
      _bannerTouchDeltaX = e.touches[0].clientX - _bannerTouchStartX;
      var pct = (-_bannerIndex * 100) + (_bannerTouchDeltaX / trackEl.offsetWidth * 100);
      trackEl.style.transform = 'translateX(' + pct + '%)';
    }, { passive: true });

    trackEl.addEventListener('touchend', function() {
      if(!_bannerDragging) return;
      _bannerDragging = false;
      trackEl.style.transition = '';
      if(_bannerTouchDeltaX > 50 && _bannerIndex > 0) {
        goToBannerSlide(_bannerIndex - 1);
      } else if(_bannerTouchDeltaX < -50 && _bannerIndex < _bannerCount - 1) {
        goToBannerSlide(_bannerIndex + 1);
      } else {
        goToBannerSlide(_bannerIndex); // повернутись на місце
      }
      _bannerTouchDeltaX = 0;
      resetBannerAutoRotate();
    });
  }

  updateBannerDynamicContent();
  startBannerAutoRotate();
}

function goToBannerSlide(idx) {
  if(idx < 0) idx = _bannerCount - 1;
  if(idx >= _bannerCount) idx = 0;
  _bannerIndex = idx;
  var trackEl = document.getElementById('bannerTrack');
  if(trackEl) trackEl.style.transform = 'translateX(-' + (idx * 100) + '%)';
  document.querySelectorAll('.banner-dot').forEach(function(d, i) {
    d.classList.toggle('active', i === idx);
  });
}

function startBannerAutoRotate() {
  clearInterval(_bannerAutoTimer);
  _bannerAutoTimer = setInterval(function() {
    goToBannerSlide(_bannerIndex + 1);
  }, 5000);
}

function resetBannerAutoRotate() {
  startBannerAutoRotate();
}

// Заповнюємо динамічні поля всередині слайдів реальними даними
function updateBannerDynamicContent() {
  // Battle Pass рівень
  var bpEl = document.getElementById('bannerBpLevel');
  if(bpEl) bpEl.textContent = getBpData().level + 1 > BP_MAX_LEVEL ? 'MAX' : getBpData().level + 1;
  // Реферальний заробіток
  var refEl = document.getElementById('bannerRefEarned');
  if(refEl) refEl.textContent = '₴' + formatNumber(userData.referralEarnings || 0);
  // BTC ціна (якщо крипто-модуль вже ініціалізований)
  var btcEl = document.getElementById('bannerBtcPrice');
  if(btcEl && typeof _cryptoPrices !== 'undefined' && _cryptoPrices.BTC) {
    btcEl.textContent = '₴' + formatNumber(Math.round(_cryptoPrices.BTC));
  } else if(btcEl) {
    btcEl.textContent = '₴95 000';
  }
  // Моє місце в денному рейтингу (та сама таблиця, що й у «Ще» → Рейтинги)
  var lbRankEl = document.getElementById('bannerLbRank');
  if(lbRankEl && db && currentUser) {
    db.ref('leaderboards/' + getLbPeriodKey('day')).once('value').then(function(snap) {
      var sorted = Object.entries(snap.val() || {})
        .map(function(e) { return { name: e[0], val: e[1].wager || 0 }; })
        .filter(function(u) { return u.val > 0; })
        .sort(function(a, b) { return b.val - a.val; });
      var i = sorted.findIndex(function(u) { return u.name === currentUser; });
      lbRankEl.textContent = i >= 0 ? '#' + (i + 1) : '—';
    }).catch(function() {});
  }
  // Місце в турнірній таблиці
  var rankEl = document.getElementById('bannerTourneyRank');
  if(rankEl && db && currentUser) {
    db.ref('leaderboard_weekly/' + currentUser + '/rank').once('value').then(function(snap) {
      rankEl.textContent = snap.exists() ? ('#' + snap.val()) : '—';
    }).catch(function() {});
  }
  // Останній результат глобальної рулетки
  var rouletteEl = document.getElementById('bannerRouletteLast');
  if(rouletteEl && db) {
    db.ref('live_results/r60').limitToLast(1).once('value').then(function(snap) {
      var vals = Object.values(snap.val() || {});
      if(!vals.length) { rouletteEl.textContent = '—'; return; }
      var last = vals[0];
      var colorDot = last.win === 'red' ? '🔴' : last.win === 'black' ? '⚫' : '🟢';
      rouletteEl.textContent = colorDot + ' ' + last.num;
    }).catch(function() {});
  }
}

// ╔══════════════════════════════════════════════════════════════╗
// ║  МОДЕРАЦІЯ v2 — бан/мут (write-side яких раніше не було),   ║
// ║  maintenance mode, живий онлайн-монітор, нотатки, kill-switch║
// ╚══════════════════════════════════════════════════════════════╝

function logAdminAction(action, details) {
  if(!currentUser) return;
  db.ref('admin_action_log').push({
    admin: currentUser, action, details: details || '', ts: Date.now()
  });
}

// ── БАН / МУТ (нарешті є сторона запису — раніше тільки перевірялось) ──
// Єдина точка бана гравця — і вкладка "Модерація" (нік/причина з полів
// форми), і швидкий бан з картки гравця (admBanUser нижче) йдуть сюди,
// щоб не було двох різних реалізацій одного й того ж запису в базу.
function banPlayer(nickArg, reasonArg) {
  if(!requireAdminPerm('moderation')) return;
  const nick = (nickArg || document.getElementById('modUserNick')?.value || '').trim();
  const reason = (reasonArg || document.getElementById('modReason')?.value || '').trim();
  if(!nick) return notify('Введи нік гравця', 'error');
  db.ref('users/' + nick).once('value').then(snap => {
    if(!snap.exists()) return notify('Гравця не знайдено', 'error');
    db.ref('users/' + nick).update({ banned: true, banReason: reason || 'Порушення правил', bannedAt: Date.now(), bannedBy: currentUser });
    logAdminAction('ban', `@${nick} — ${reason || 'без причини'}`);
    notify('🚫 Гравця ' + nick + ' забанено', 'success');
  });
}

function unbanPlayer() {
  if(!requireAdminPerm('moderation')) return;
  const nick = (document.getElementById('modUserNick')?.value || '').trim();
  if(!nick) return notify('Введи нік гравця', 'error');
  db.ref('users/' + nick).update({ banned: false, banReason: null });
  logAdminAction('unban', `@${nick}`);
  notify('✅ Гравця ' + nick + ' розблоковано', 'success');
}

function mutePlayer() {
  if(!requireAdminPerm('moderation')) return;
  const nick = (document.getElementById('modUserNick')?.value || '').trim();
  const reason = (document.getElementById('modReason')?.value || '').trim();
  const hours = parseInt(document.getElementById('modMuteHours')?.value) || 1;
  if(!nick) return notify('Введи нік гравця', 'error');
  db.ref('users/' + nick).once('value').then(snap => {
    if(!snap.exists()) return notify('Гравця не знайдено', 'error');
    db.ref('users/' + nick).update({ muted: true, muteReason: reason || '', muteUntil: Date.now() + hours*3600000 });
    logAdminAction('mute', `@${nick} на ${hours}год — ${reason || 'без причини'}`);
    notify('🔇 Гравця ' + nick + ' замучено на ' + hours + 'год', 'success');
  });
}

function unmutePlayer() {
  if(!requireAdminPerm('moderation')) return;
  const nick = (document.getElementById('modUserNick')?.value || '').trim();
  if(!nick) return notify('Введи нік гравця', 'error');
  db.ref('users/' + nick).update({ muted: false, muteUntil: null });
  logAdminAction('unmute', `@${nick}`);
  notify('🔊 Гравця ' + nick + ' розмучено', 'success');
}

// ── MAINTENANCE MODE ──
function toggleMaintenanceMode() {
  if(!requireAdminPerm('moderation')) return;
  db.ref('site_config/maintenance').once('value').then(snap => {
    const newState = !snap.val();
    db.ref('site_config/maintenance').set(newState);
    logAdminAction('maintenance', newState ? 'Увімкнено' : 'Вимкнено');
    const btn = document.getElementById('maintenanceToggleBtn');
    if(btn) {
      btn.textContent = newState ? '✅ Вимкнути обслуговування' : '🚧 Увімкнути обслуговування';
      btn.className = newState ? 'btn-outline' : 'btn-red';
    }
    notify(newState ? '🚧 Режим обслуговування УВІМКНЕНО — нові входи заблоковані' : '✅ Сайт знову доступний всім', newState ? 'error' : 'success');
  });
}

function loadMaintenanceStatus() {
  db.ref('site_config/maintenance').once('value').then(snap => {
    const btn = document.getElementById('maintenanceToggleBtn');
    if(!btn) return;
    const on = !!snap.val();
    btn.textContent = on ? '✅ Вимкнути обслуговування' : '🚧 Увімкнути обслуговування';
    btn.className = on ? 'btn-outline' : 'btn-red';
  });
}

// ── ЖИВИЙ ОНЛАЙН-МОНІТОР ──
function loadOnlinePlayersAdmin() {
  const el = document.getElementById('adminOnlineList');
  if(!el) return;
  el.innerHTML = '<div style="color:var(--fg-4);text-align:center;padding:14px;">Завантаження...</div>';
  db.ref('users').orderByChild('lastSeen').limitToLast(40).once('value').then(snap => {
    const users = snap.val() || {};
    const now = Date.now();
    const online = Object.entries(users)
      .filter(([nick, u]) => u.lastSeen && now - u.lastSeen < 300000 && !u.isBot)
      .sort((a,b) => (b[1].lastSeen||0) - (a[1].lastSeen||0));
    if(!online.length) { el.innerHTML = '<div style="color:var(--fg-4);text-align:center;padding:14px;">Нікого онлайн</div>'; return; }
    el.innerHTML = online.map(([nick, u]) => {
      const minsAgo = Math.floor((now - u.lastSeen) / 60000);
      const statusColor = minsAgo < 2 ? '#3dd68c' : '#f39c12';
      return `<div style="display:flex;align-items:center;gap:10px;padding:8px;background:var(--surface-1);border-radius:var(--r-md);margin-bottom:6px;">
        <div style="width:8px;height:8px;border-radius:50%;background:${statusColor};flex-shrink:0;"></div>
        <div style="flex:1;min-width:0;">
          <div style="font-weight:700;font-size:12px;">${nick}${u.banned?' 🚫':''}${u.muted?' 🔇':''}${u.flagged?' 🚩':''}</div>
          <div style="font-size:10px;color:var(--fg-4);">₴${formatNumber(u.balance||0)} · ${minsAgo}хв тому</div>
        </div>
        <button onclick="document.getElementById('modUserNick').value='${nick}';notify('Нік підставлено в поле модерації','info')" style="background:rgb(var(--neg-rgb) / 0.08);border:1px solid var(--line);border-radius:var(--r-sm);color:var(--fg-3);font-size:10px;padding:4px 8px;cursor:pointer;">⚙️</button>
        <button onclick="document.getElementById('pmToInput')?document.getElementById('pmToInput').value='${nick}':null;switchTab('pm')" style="background:rgb(var(--info-rgb) / 0.08);border:1px solid var(--line);border-radius:var(--r-sm);color:var(--info);font-size:10px;padding:4px 8px;cursor:pointer;">✉️</button>
      </div>`;
    }).join('');
  });
}

// ── НОТАТКИ АДМІНА ПРО ГРАВЦЯ ──
function loadPlayerNotes() {
  const nick = (document.getElementById('notesUserNick')?.value || '').trim();
  if(!nick) return notify('Введи нік гравця', 'error');
  db.ref('admin_notes/' + nick).once('value').then(snap => {
    const el = document.getElementById('playerNotesText');
    if(el) el.value = snap.val()?.text || '';
    notify('📝 Нотатки завантажено', 'info');
  });
}

function savePlayerNotes() {
  const nick = (document.getElementById('notesUserNick')?.value || '').trim();
  const text = document.getElementById('playerNotesText')?.value || '';
  if(!nick) return notify('Введи нік гравця', 'error');
  db.ref('admin_notes/' + nick).set({ text, updatedBy: currentUser, updatedAt: Date.now() });
  logAdminAction('note', `Оновлено нотатку про @${nick}`);
  notify('💾 Нотатку збережено', 'success');
}

